azureLogAnalytics.query:
let inviateConSuccesso = toscalar(
    AppTraces
    | where $__timeFilter(TimeGenerated)
    | where AppRoleName == "rtp-sender"
    | where Message startswith "Rtp sent successfully with id:"
    | count
    | project Count
);
let payerNonAttivato = toscalar(
    AppTraces
    | where $__timeFilter(TimeGenerated)
    | where AppRoleName == "rtp-sender"
    | where Message startswith "Error sending Rtp to be sent:"
    | where Message has "payer is not activated" or Message has "The payer is not activated"
    | count
    | project Count
);
print ["Active Payer Reachability %"] = round(100.0 * inviateConSuccesso / iff((inviateConSuccesso + payerNonAttivato) == 0, 1, inviateConSuccesso + payerNonAttivato), 2), ["Inviate con successo"] = inviateConSuccesso, ["Payer non attivato"] = payerNonAttivato
